207	class WorksHitRuntime {
208	  private readonly _raycaster = new THREE.Raycaster();
209	  private readonly _mouse2d = new THREE.Vector2();
210	
211	  resolve(
212	    camera: THREE.Camera,
213	    viewport: WorksViewportSnapshot,
214	    pointer: WorksPointerSample,
215	    meshes: THREE.Mesh[],
216	  ): THREE.Mesh | null {
217	    this._mouse2d.set(
218	      (pointer.x / viewport.width) * 2 - 1,
219	      -(pointer.y / viewport.height) * 2 + 1,
220	    );
221	    this._raycaster.setFromCamera(this._mouse2d, camera);
222	    const hit = this._raycaster.intersectObjects(meshes, false)[0];
223	    return (hit?.object as THREE.Mesh | undefined) ?? null;
224	  }
225	}
