227	class WorksCameraMotionRuntime {
228	  private readonly _layout: WorkLayoutConstants;
229	  private readonly _camPadX: number;
230	  private readonly _camPadY: number;
231	  private _baseCamZ: number;
232	  private _isDragging = false;
233	  private _dragPrevious: WorksPointerSample = { x: 0, y: 0 };
234	  private _targetX = 0;
235	  private _targetY = 0;
236	  private _velocityX = 0;
237	  private _velocityY = 0;
238	  private _targetZ: number;
239	  private _dynClampMinX: number;
240	  private _dynClampMaxX: number;
241	  private _dynClampMinY: number;
242	  private _dynClampMaxY: number;
243	
244	  constructor(
245	    layout: WorkLayoutConstants,
246	    camPadX: number,
247	    camPadY: number,
248	    camZ: number,
249	  ) {
250	    this._layout = layout;
251	    this._camPadX = camPadX;
252	    this._camPadY = camPadY;
253	    this._baseCamZ = camZ;
254	    this._targetZ = camZ;
255	    this._dynClampMinX = -camPadX;
256	    this._dynClampMaxX = camPadX;
257	    this._dynClampMinY = -camPadY;
258	    this._dynClampMaxY = camPadY;
259	  }
260	
261	  setDynamicClamp(positions: ReadonlyArray<WorksScatterPosition>): void {
262	    if (positions.length === 0) {
263	      this._dynClampMinX = this._dynClampMaxX = 0;
264	      this._dynClampMinY = this._dynClampMaxY = 0;
265	      return;
266	    }
267	    const MARGIN = 8;
268	    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
269	    for (const p of positions) {
270	      if (p.x < minX) minX = p.x;
271	      if (p.x > maxX) maxX = p.x;
272	      if (p.y < minY) minY = p.y;
273	      if (p.y > maxY) maxY = p.y;
274	    }
275	    this._dynClampMinX = minX - MARGIN;
276	    this._dynClampMaxX = maxX + MARGIN;
277	    this._dynClampMinY = minY - MARGIN;
278	    this._dynClampMaxY = maxY + MARGIN;
279	  }
280	
281	  activateScatter(): void {
282	    this._targetZ = this._baseCamZ;
283	  }
284	
285	  setTargetPosition(targetX: number, targetY: number): void {
286	    this._targetX = targetX;
287	    this._targetY = targetY;
288	  }
289	
290	  snapToPosition(camera: THREE.Camera, targetX: number, targetY: number): void {
291	    this._targetX = targetX;
292	    this._targetY = targetY;
293	    this._velocityX = 0;
294	    this._velocityY = 0;
295	    camera.position.x = targetX;
296	    camera.position.y = targetY;
297	    camera.lookAt(targetX, targetY, 0);
298	  }
299	
300	  setTargetZ(targetZ: number): void {
301	    this._targetZ = targetZ;
302	  }
303	
304	  readBaseCamZ(): number {
305	    return this._baseCamZ;
306	  }
307	
308	  setBaseCamZ(baseCamZ: number): void {
309	    this._baseCamZ = baseCamZ;
310	    this._targetZ = baseCamZ;
311	  }
312	
313	  primeFromCamera(camera: THREE.PerspectiveCamera): void {
314	    this._targetX = camera.position.x;
315	    this._targetY = camera.position.y;
316	    this._targetZ = camera.position.z;
317	  }
318	
319	  primeFromCameraPosition(targetX: number, targetY: number, targetZ: number): void {
320	    this._targetX = targetX;
321	    this._targetY = targetY;
322	    this._targetZ = targetZ;
323	  }
324	
325	  beginDrag(camera: THREE.Camera, pointer: WorksPointerSample): void {
326	    this._isDragging = true;
327	    this._dragPrevious = { ...pointer };
328	    this._velocityX = 0;
329	    this._velocityY = 0;
330	    this._targetX = camera.position.x;
331	    this._targetY = camera.position.y;
332	  }
333	
334	  endDrag(): void {
335	    this._isDragging = false;
336	  }
337	
338	  updateDrag(
339	    viewport: WorksViewportSnapshot,
340	    halfView: WorksHalfViewBounds,
341	    pointer: WorksPointerSample,
342	    velMultiplier = 1,
343	  ): void {
344	    if (!this._isDragging) return;
345	    const dx = pointer.x - this._dragPrevious.x;
346	    const dy = pointer.y - this._dragPrevious.y;
347	    this._targetX += (-dx * (halfView.hW * 2)) / viewport.width;
348	    this._targetY += (dy * (halfView.hH * 2)) / viewport.height;
349	    this._velocityX = ((-dx * (halfView.hW * 2)) / viewport.width) * 0.7 * velMultiplier;
350	    this._velocityY = ((dy * (halfView.hH * 2)) / viewport.height) * 0.7 * velMultiplier;
351	    this._targetX = Math.max(
352	      this._dynClampMinX + halfView.hW,
353	      Math.min(this._dynClampMaxX - halfView.hW, this._targetX),
354	    );
355	    this._targetY = Math.max(
356	      this._dynClampMinY + halfView.hH,
357	      Math.min(this._dynClampMaxY - halfView.hH, this._targetY),
358	    );
359	    this._dragPrevious = { ...pointer };
360	  }
361	
362	  updateFrame(camera: THREE.Camera, delta: number): void {
363	    if (this._isDragging) {
364	      const decay = Math.pow(this._layout.velDecay, delta * 60);
365	      this._velocityX *= decay;
366	      this._velocityY *= decay;
367	      this._targetX += this._velocityX * delta * 60;
368	      this._targetY += this._velocityY * delta * 60;
369	    }
370	    const camFactor = 1 - Math.pow(1 - this._layout.camLerp, delta * 60);
371	    camera.position.x += (this._targetX - camera.position.x) * camFactor;
372	    camera.position.y += (this._targetY - camera.position.y) * camFactor;
373	    const camZFactor = 1 - Math.pow(1 - this._layout.camZLerp, delta * 60);
374	    camera.position.z += (this._targetZ - camera.position.z) * camZFactor;
375	    camera.lookAt(camera.position.x, camera.position.y, 0);
376	  }
377	
378	  get isDragging(): boolean {
379	    return this._isDragging;
380	  }
381	}
