383	class WorksMeshRuntime {
384	  create(
385	    scene: THREE.Scene,
386	    projects: ReadonlyArray<WorkProjectItem>,
387	    positions: ReadonlyArray<WorksScatterPosition>,
388	    config: WorkCanvasConfig,
389	  ): WorksSceneCardMeshResources {
390	    const cardSize: WorkCardSize = {
391	      w: config.cardWidth,
392	      h: config.cardHeight,
393	    };
394	    const meshes: THREE.Mesh[] = [];
395	    positions.forEach((position, placed) => {
396	      const project = projects[placed % projects.length];
397	      const detailPath = project?.detailPath ?? "/works";
398	      const mesh = WorkCard.createMesh(
399	        project,
400	        cardSize,
401	        detailPath,
402	        SCATTER_CARD_RENDER_OPTIONS,
403	      );
404	      mesh.position.set(position.x, position.y, 0);
405	      scene.add(mesh);
406	      meshes.push(mesh);
407	    });
408	    return {
409	      meshes,
410	      cardSize,
411	    };
412	  }
413	
414	  dispose(meshes: ReadonlyArray<THREE.Mesh>): void {
415	    meshes.forEach((mesh) => {
416	      const material = mesh.material as THREE.MeshBasicMaterial;
417	      material.map?.dispose();
418	      material.dispose();
419	      mesh.geometry.dispose();
420	    });
421	  }
422	}
