485	export class WorksSceneManager {
486	  private static readonly _dragStartThresholdPx = 10;
487	  /** 카테고리 전환 시 등장/퇴장 이징 길이(ms) — 전체 복귀 시 숨겨졌던 카드도 위치·투명도가 눈에 띄게 변함 */
488	  private static readonly _filterBlendMs = 480;
489	  private readonly root: ParentNode;
490	  private readonly config: WorkCanvasConfig;
491	  private readonly layout: WorkLayoutConstants;
492	  private readonly projects: ReadonlyArray<WorkProjectItem>;
493	  private readonly canvasId: string;
494	  private readonly rendererConfig: WorksRendererConfig;
495	  private readonly placeholderImage: string;
496	  private readonly introEntryState: WorksSceneManagerOptions["introEntryState"];
497	  private readonly viewportRuntime: WorksViewportRuntime;
498	  private readonly hitRuntime = new WorksHitRuntime();
499	  private readonly meshRuntime = new WorksMeshRuntime();
500	  private readonly thumbnailRuntime = new WorksThumbnailRuntime();
501	  private readonly cameraMotionRuntime: WorksCameraMotionRuntime;
502	  private readonly onSelect?: (detailPath: string) => void;
503	  private readonly onInteractionStart?: () => void;
504	  private canvas: HTMLCanvasElement | null = null;
505	  private scene: THREE.Scene | null = null;
506	  private camera: THREE.Camera | null = null;
507	  private renderer: THREE.WebGLRenderer | null = null;
508	  private meshes: THREE.Mesh[] = [];
509	  private rafId: number | null = null;
510	  private cleanup: Array<() => void> = [];
511	  private viewMode: WorksViewMode = "scatter";
512	  private clock: THREE.Clock | null = null;
513	  private activePointerId: number | null = null;
514	  private hovered: THREE.Mesh | null = null;
515	  private _prevHovered: THREE.Mesh | null = null;
516	  private _cardScale = 1;
517	  private _cardSize: WorkCardSize = { w: 10, h: 6.9 };
518	  private _isTouchPointer = false;
519	  private readonly _hoverVideo = new WorksHoverVideoRuntime();
520	  private mouseDownX = 0;
521	  private mouseDownY = 0;
522	  private mouseDownMesh: THREE.Mesh | null = null;
523	  private dragInteractionStarted = false;
524	  private readonly camPadX: number;
525	  private readonly camPadY: number;
526	  private scatterPositions: WorksScatterPosition[];
527	  private categoryScatterPositions: WorksScatterPosition[];
528	  private targetPositions: WorksScatterPosition[] = [];
529	  private interactiveMeshes: THREE.Mesh[] = [];
530	  private activeCategory: string | null;
531	  /** 직전 `applyCategory` 호출 직전의 필터 (전환 이징용) */
532	  private _filterPrevCategory: string | null = null;
533	  private _filterBlendStartMs = 0;
534	
535	  constructor(options: WorksSceneManagerOptions) {
536	    this.root = options.root;
537	    this.config = options.config;
538	    this.layout = options.layout;
539	    this.projects = options.projects;
540	    this.canvasId = options.canvasId;
541	    this.rendererConfig = options.renderer;
542	    this.placeholderImage = options.placeholderImage;
543	    this.introEntryState = options.introEntryState ?? null;
544	    this.onSelect = options.onSelect;
545	    this.onInteractionStart = options.onInteractionStart;
546	    this.activeCategory = options.initialCategory ?? null;
547	    this.camPadX = options.config.spreadX * 0.5 + 5;
548	    this.camPadY = options.config.spreadY * 0.5 + 5;
549	    this.viewportRuntime = new WorksViewportRuntime(options.pixelRatioMax);
550	    this.cameraMotionRuntime = new WorksCameraMotionRuntime(
551	      options.layout,
552	      this.camPadX,
553	      this.camPadY,
554	      options.config.camZ,
555	    );
556	    this.scatterPositions = buildScatterPositions(
557	      options.config.totalCards,
558	      options.config.spreadX,
559	      options.config.spreadY * 0.88,
560	    );
561	    this.categoryScatterPositions = sortScatterPositionsFromCenter(this.scatterPositions);
562	    this.targetPositions = [...this.scatterPositions];
563	  }
564	
565	  private _rebuildScatterPositions(): void {
566	    const scale = this._cardScale;
567	    this.scatterPositions = buildScatterPositions(
568	      this.config.totalCards,
569	      this.config.spreadX * scale,
570	      this.config.spreadY * 0.88 * scale,
571	    );
572	    this.categoryScatterPositions = sortScatterPositionsFromCenter(this.scatterPositions);
573	  }
574	
575	  init(): void {
576	    if (this.projects.length === 0) return;
577	    this.start();
578	  }
579	
580	  setViewMode(mode: WorksViewMode): void {
581	    if (this.viewMode === mode) return;
582	    this.viewMode = mode;
583	    if (mode === "grid") {
584	      this._hoverVideo.deactivate();
585	      this._prevHovered = null;
586	      this.hovered = null;
587	      this.mouseDownMesh = null;
588	      this.dragInteractionStarted = false;
589	      this.activePointerId = null;
590	      this.cameraMotionRuntime.endDrag();
591	      this.stopLoop();
592	      return;
593	    }
594	    this.cameraMotionRuntime.activateScatter();
595	    this.startLoop();
596	  }
597	
598	  applyCategory(category: string | null): void {
599	    if (this.activeCategory !== category) {
600	      this._filterPrevCategory = this.activeCategory;
601	      this._filterBlendStartMs = performance.now();
602	    }
603	    this.activeCategory = category;
604	    const scatterPositions = this.categoryScatterPositions;
605	    const nextPositions = [...this.scatterPositions];
606	    const nextInteractiveMeshes: THREE.Mesh[] = [];
607	    const visiblePositions: WorksScatterPosition[] = [];
608	    let visibleIndex = 0;
609	    for (let index = 0; index < this.meshes.length; index += 1) {
610	      const mesh = this.meshes[index];
611	      if (!mesh || !this.isMeshInCategory(mesh)) continue;
612	      nextInteractiveMeshes.push(mesh);
613	      const targetPosition = scatterPositions[visibleIndex] ?? this.scatterPositions[index];
614	      nextPositions[index] = targetPosition;
615	      visiblePositions.push(targetPosition);
616	      visibleIndex += 1;
617	    }
618	    this.targetPositions = nextPositions;
619	    this.interactiveMeshes = nextInteractiveMeshes;
