829	  private bindEvents(): void {
830	    const canvas = this.canvas;
831	    if (!canvas) return;
832	
833	    const onPointerMove = (event: PointerEvent): void => {
834	      const viewport = this.viewportRuntime.read();
835	      if (this.viewMode !== "scatter") {
836	        this.hovered = null;
837	        return;
838	      }
839	      if (!this.camera) return;
840	      if (this.activePointerId !== event.pointerId) {
841	        if (this.activePointerId === null) {
842	          this.hovered = this.hitRuntime.resolve(
843	            this.camera,
844	            viewport,
845	            { x: event.clientX, y: event.clientY },
846	            this.interactiveMeshes,
847	          );
848	        }
849	        return;
850	      }
851	      if (this.cameraMotionRuntime.isDragging) {
852	        if (
853	          !this.dragInteractionStarted &&
854	          Math.hypot(event.clientX - this.mouseDownX, event.clientY - this.mouseDownY) >=
855	            WorksSceneManager._dragStartThresholdPx
856	        ) {
857	          this.dragInteractionStarted = true;
858	          this.onInteractionStart?.();
859	        }
860	        this.cameraMotionRuntime.updateDrag(
861	          viewport,
862	          this.viewportRuntime.readHalfView(this.camera),
863	          { x: event.clientX, y: event.clientY },
864	          this._isTouchPointer ? 2.0 : 1.0,
865	        );
866	        this.hovered = null;
867	        return;
868	      }
869	      this.hovered = this.hitRuntime.resolve(
870	        this.camera,
871	        viewport,
872	        { x: event.clientX, y: event.clientY },
873	        this.interactiveMeshes,
874	      );
875	    };
876	    const onPointerDown = (event: PointerEvent): void => {
877	      if (this.viewMode !== "scatter" || !this.camera) return;
878	      if (event.button !== 0) return;
879	      this.mouseDownX = event.clientX;
880	      this.mouseDownY = event.clientY;
881	      this.dragInteractionStarted = false;
882	      this.activePointerId = event.pointerId;
883	      this._isTouchPointer = event.pointerType === "touch";
884	      this.mouseDownMesh = this.hitRuntime.resolve(
885	        this.camera,
886	        this.viewportRuntime.read(),
887	        { x: event.clientX, y: event.clientY },
888	        this.interactiveMeshes,
889	      );
890	      this.cameraMotionRuntime.beginDrag(this.camera, {
891	        x: event.clientX,
892	        y: event.clientY,
893	      });
894	      canvas.setPointerCapture(event.pointerId);
895	    };
896	    const onPointerUp = (event: PointerEvent): void => {
897	      if (this.activePointerId !== event.pointerId) return;
898	      if (
899	        this.viewMode === "scatter" &&
900	        this.mouseDownMesh &&
901	        this.isMeshInCategory(this.mouseDownMesh) &&
902	        Math.hypot(event.clientX - this.mouseDownX, event.clientY - this.mouseDownY) <
903	          WorksSceneManager._dragStartThresholdPx
904	      ) {
905	        const userData = this.mouseDownMesh.userData as WorkCardUserData;
906	        this.onSelect?.(userData.detailPath);
907	      }
908	      this._resetPointerInteraction(event.pointerId);
909	    };
910	    const onPointerCancel = (event: PointerEvent): void => {
911	      if (this.activePointerId !== event.pointerId) return;
912	      this._resetPointerInteraction(event.pointerId);
913	    };
914	    const onPointerLeave = (): void => {
915	      if (this.activePointerId !== null) return;
916	      this.hovered = null;
917	    };
918	    const onResize = (): void => {
919	      if (!this.camera || !this.renderer) return;
920	      const viewport = this.viewportRuntime.read();
921	      if (this.camera instanceof THREE.OrthographicCamera) {
922	        const halfHeight =
923	          Math.tan((this.config.camFov * Math.PI) / 360) * this.config.camZ;
924	        const halfWidth = halfHeight * (viewport.width / viewport.height);
925	        this.camera.left = -halfWidth;
926	        this.camera.right = halfWidth;
927	        this.camera.top = halfHeight;
928	        this.camera.bottom = -halfHeight;
929	        this.camera.updateProjectionMatrix();
930	      }
931	      this.renderer.setPixelRatio(viewport.dpr);
932	      this.renderer.setSize(viewport.width, viewport.height);
933	      const resizeScaleBase = viewport.width < 768 ? CARD_SCALE_MOBILE_BASE_WIDTH : CARD_SCALE_BASE_WIDTH;
934	      const nextCardScale = Math.min(1, viewport.width / resizeScaleBase);
935	      if (nextCardScale !== this._cardScale) {
936	        this._cardScale = nextCardScale;
937	        this._rebuildScatterPositions();
938	      }
939	      this.applyCategory(this.activeCategory);
940	    };
941	    canvas.addEventListener("pointermove", onPointerMove);
942	    canvas.addEventListener("pointerdown", onPointerDown);
943	    canvas.addEventListener("pointerup", onPointerUp);
944	    canvas.addEventListener("pointercancel", onPointerCancel);
945	    canvas.addEventListener("pointerleave", onPointerLeave);
946	    window.addEventListener("resize", onResize);
947	    this.cleanup.push(
948	      () => canvas.removeEventListener("pointermove", onPointerMove),
949	      () => canvas.removeEventListener("pointerdown", onPointerDown),
950	      () => canvas.removeEventListener("pointerup", onPointerUp),
951	      () => canvas.removeEventListener("pointercancel", onPointerCancel),
952	      () => canvas.removeEventListener("pointerleave", onPointerLeave),
953	      () => window.removeEventListener("resize", onResize),
954	    );
955	  }
