957	  private startLoop(): void {
958	    if (this.rafId !== null) return;
959	    if (!this.camera || !this.renderer || !this.scene) return;
960	    this.clock = new THREE.Clock();
961	    this.clock.start();
962	    const animate = (): void => {
963	      if (!this.camera || !this.renderer || !this.scene || !this.clock) {
964	        this.rafId = null;
965	        return;
966	      }
967	      this.rafId = FrameScheduler.request(animate);
968	      const delta = Math.min(this.clock.getDelta(), MAX_DELTA_SECONDS);
969	      this.update(delta);
970	      this.renderer.render(this.scene, this.camera);
971	    };
972	    animate();
973	  }
