1006	  private _centerCameraOnVisiblePositions(
1007	    positions: ReadonlyArray<WorksScatterPosition>,
1008	  ): void {
1009	    if (!this.camera) {
1010	      const center = this._readVisiblePositionsCenter(positions);
1011	      this.cameraMotionRuntime.setTargetPosition(center.x, center.y);
1012	      return;
1013	    }
1014	    // 카테고리 변경 시 target 위치(아직 비어있음)가 아닌
1015	    // 현재 메시의 실제 위치 centroid로 스냅 → lerp 시작 순간에도 메시가 화면에 보임
1016	    const meshes = this.interactiveMeshes;
1017	    if (meshes.length === 0) {
1018	      const center = this._readVisiblePositionsCenter(positions);
1019	      this.cameraMotionRuntime.snapToPosition(this.camera, center.x, center.y);
1020	      return;
1021	    }
1022	    let sumX = 0;
1023	    let sumY = 0;
1024	    for (const mesh of meshes) {
1025	      sumX += mesh.position.x;
1026	      sumY += mesh.position.y;
1027	    }
1028	    this.cameraMotionRuntime.snapToPosition(
1029	      this.camera,
1030	      sumX / meshes.length,
1031	      sumY / meshes.length,
1032	    );
1033	  }
1034	
1035	  private _readVisiblePositionsCenter(
1036	    positions: ReadonlyArray<WorksScatterPosition>,
1037	  ): WorksScatterPosition {
1038	    if (positions.length === 0) {
1039	      return { x: 0, y: 0 };
1040	    }
1041	    let minX = positions[0]?.x ?? 0;
1042	    let maxX = minX;
1043	    let minY = positions[0]?.y ?? 0;
1044	    let maxY = minY;
1045	    for (let index = 1; index < positions.length; index += 1) {
1046	      const position = positions[index];
1047	      if (!position) continue;
1048	      minX = Math.min(minX, position.x);
1049	      maxX = Math.max(maxX, position.x);
1050	      minY = Math.min(minY, position.y);
1051	      maxY = Math.max(maxY, position.y);
1052	    }
1053	    return {
1054	      x: (minX + maxX) * 0.5,
1055	      y: (minY + maxY) * 0.5,
1056	    };
1057	  }
1058	}
