51	/** 별도 캔버스에 메인 배경(우주)만 재생 — works 메인 캔버스와 분리 */
52	export class WorksBackgroundRuntime {
53	  private static readonly _readyTimeoutMs = 2000;
54	  private _engine: Engine | null = null;
55	  private _objectSetup: ObjectSetup | null = null;
56	  private _canvasElement: HTMLCanvasElement | null = null;
57	  private _readyFrameId: number | null = null;
58	
59	  async run(canvasId: string, canvasElement: HTMLCanvasElement): Promise<void> {
60	    if (this._engine && this._canvasElement === canvasElement) return;
61	    if (this._engine) {
62	      this.dispose();
63	    }
64	    const engine = createWorksEngine(canvasId, canvasElement);
65	    if (!engine.init()) return;
66	    this._engine = engine;
67	    this._canvasElement = canvasElement;
68	    this._objectSetup = new ObjectSetup();
69	    const config = WorksSceneDefinition.createBackgroundPageConfig(canvasId);
70	    await this._objectSetup.init(engine, config);
71	    const runtimeState = WorksSceneDefinition.createBackgroundRuntimeState();
72	    engine
73	      .getBackgroundManager()
74	      ?.setRuntimeState(mainBackground, runtimeState);
75	    engine.start(() => undefined, () => undefined);
76	    await this._waitUntilReady(engine);
77	  }
78	
79	  dispose(): void {
80	    if (this._readyFrameId !== null) {
81	      FrameScheduler.cancel(this._readyFrameId);
82	      this._readyFrameId = null;
83	    }
84	    this._objectSetup?.dispose();
85	    this._objectSetup = null;
86	    this._engine?.dispose();
87	    this._engine = null;
88	    this._canvasElement = null;
89	  }
90	
91	  private _waitUntilReady(engine: Engine): Promise<void> {
92	    return new Promise<void>((resolve, reject) => {
93	      const startedAt = resolveTimestamp();
94	      const tick = (): void => {
95	        if (this._engine !== engine) {
96	          this._readyFrameId = null;
97	          resolve();
98	          return;
99	        }
100	        const backgroundManager = engine.getBackgroundManager();
101	        if (backgroundManager?.hasRenderedFrame()) {
102	          this._readyFrameId = null;
103	          resolve();
104	          return;
105	        }
106	        if (
107	          resolveTimestamp() - startedAt > WorksBackgroundRuntime._readyTimeoutMs
108	        ) {
109	          this._readyFrameId = null;
110	          reject(
111	            new Error(
112	              "[WorksBackgroundRuntime._waitUntilReady] Background render timed out.",
113	            ),
114	          );
115	          return;
116	        }
117	        this._readyFrameId = FrameScheduler.request(tick);
118	      };
119	      this._readyFrameId = FrameScheduler.request(tick);
120	    });
121	  }
122	}
