250	class WorksTheatreRuntime {
251	  private static _instance: WorksTheatreRuntime | null = null;
252	
253	  private readonly _config: WorksIntroTheatreConfig;
254	  private readonly _stateSource: Record<string, unknown> | null;
255	  private readonly _project: TheatreProjectPort<Record<string, unknown>, Record<string, unknown>>;
256	  private readonly _ready: Promise<void>;
257	  private readonly _objectBySheetId = new Map<WorksTheatreSheetId, { value: Record<string, unknown> }>();
258	  private readonly _sequenceBySheetId = new Map<WorksTheatreSheetId, TheatreSequencePort>();
259	  private readonly _lengthBySheetId = new Map<WorksTheatreSheetId, number>();
260	  private readonly _cameraPlaybackRangeBySheetId = new Map<
261	    WorksTheatreSheetId,
262	    WorksTheatrePlaybackRange
263	  >();
264	
265	  private constructor() {
266	    this._config = readWorksTheatreConfigSource();
267	    this._stateSource = readWorksTheatreStateSource();
268	    this._project = TheatreProjectSession.open<Record<string, unknown>, Record<string, unknown>>(
269	      WORKS_THEATRE_PROJECT_ID,
270	      this._stateSource ? { state: this._stateSource } : undefined,
271	    );
272	    this._ready = Promise.resolve(this._project.ready).then(() => undefined);
273	    WORKS_THEATRE_SHEET_IDS.forEach((sheetId) => {
274	      const sheet = TheatreSheetSession.open(this._project, sheetId);
275	      const object = sheet.object(
276	        WORKS_THEATRE_OBJECT_ID,
277	        readWorksInitialObjectState(
278	          this._stateSource,
279	          sheetId,
280	        ) as unknown as Record<string, unknown>,
281	        { reconfigure: true },
282	      );
283	      const length = this._resolveSheetLength(sheetId, sheet.sequence);
284	      const cameraRange = this._resolveCameraPreviewRange(sheetId, length);
285	      this._objectBySheetId.set(sheetId, object);
286	      this._sequenceBySheetId.set(sheetId, sheet.sequence);
287	      this._lengthBySheetId.set(sheetId, length);
288	      if (cameraRange) {
289	        this._cameraPlaybackRangeBySheetId.set(sheetId, cameraRange);
290	      }
291	    });
292	  }
293	
294	  static getInstance(): WorksTheatreRuntime {
295	    if (!WorksTheatreRuntime._instance) {
296	      WorksTheatreRuntime._instance = new WorksTheatreRuntime();
