126	function createWorksAuthorSceneState(state: WorksAuthorState): SceneFromState {
127	  const windowPosition = state.window?.position ?? { x: 0, y: 0, z: 0 };
128	  const windowRotation = state.window?.rotation ?? { x: 0, y: 0, z: 0 };
129	  const windowScale = state.window?.scale ?? { x: 1, y: 1, z: 1 };
130	  return {
131	    camera: {
132	      position: { ...state.camera.position },
133	      fov: state.camera.fov,
134	    },
135	    cameraTarget: {
136	      position: { ...state.camera.target },
137	    },
138	    [sceneLights]: {
