140	      ground: {
141	        position: { ...state.sceneLights.ground.position },
142	        rotation: { ...state.sceneLights.ground.rotation },
143	        scale: { ...state.sceneLights.ground.scale },
144	        visible: state.sceneLights.ground.visible,
145	      },
146	    } as Record<string, unknown>,
147	    [windowObj]: {
148	      position: { ...windowPosition },
149	      rotation: { ...windowRotation },
150	      scale: { ...windowScale },
151	      visible: state.window?.visible ?? true,
152	    } as Record<string, unknown>,
153	  };
154	}
