181	export class WorksTheatreBridge {
182	  private static readonly _statusId = "works-theatre-status";
183	  private static readonly _exportButtonId = "works-theatre-export";
184	  private static readonly _sheetSelectId = "works-theatre-sheet-select";
185	
186	  private _engine: Engine | null = null;
187	  private _objectSetup: ObjectSetup | null = null;
188	  private _controls: OrbitControls | null = null;
189	  private _authorSheetId: WorksTheatreSheetId = WORKS_THEATRE_SHEET_IDS[0] ?? "works";
190	  private readonly _sheetById = new Map<
191	    WorksTheatreSheetId,
192	    TheatreSheetPort<WorksAuthorState, WorksAuthorState>
193	  >();
194	  private readonly _objectBySheetId = new Map<
195	    WorksTheatreSheetId,
196	    TheatreObjectPort<WorksAuthorState, WorksAuthorState>
197	  >();
198	  private _unsubscribeValues: (() => void) | null = null;
199	  private _recordScrub: TheatreScrubPort<WorksAuthorState, WorksAuthorState> | null =
200	    null;
201	  private _sampling = false;
202	  private _lastSampleAt = 0;
203	  private readonly _onControlsStart = () => this._recordStart();
204	  private readonly _onControlsEnd = () => this._recordEnd();
205	  private readonly _onControlsChange = () => this._recordFrame();
206	  private readonly _onExportClick = () => void this._exportSaveFile();
207	  private readonly _onSheetChange = (event: Event) => {
208	    const select = event.currentTarget;
