383	  private _renderExportButton(): void {
384	    TheatreStudioService.renderAuthorButton(
385	      {
386	        id: WorksTheatreBridge._exportButtonId,
387	        text: "EXPORT STATE JSON",
388	        bottom: "16px",
389	      },
390	      this._onExportClick,
391	    );
392	  }
