394	  private _renderSheetSelector(): void {
395	    if (WORKS_THEATRE_SHEET_IDS.length <= 1) {
396	      TheatreStudioService.removeAuthorControl(
397	        WorksTheatreBridge._sheetSelectId,
398	        "select",
399	        this._onSheetChange as EventListener,
400	      );
401	      return;
402	    }
403	    TheatreStudioService.renderAuthorSelect(
404	      {
405	        id: WorksTheatreBridge._sheetSelectId,
406	        bottom: "92px",
407	        value: this._authorSheetId,
408	        options: WORKS_THEATRE_SHEET_IDS.map((sheetId) => ({
409	          value: sheetId,
410	          text: sheetId,
411	        })),
412	      },
413	      this._onSheetChange,
414	    );
415	  }
416	
417	  private _renderStatus(text: string): void {
418	    TheatreStudioService.renderAuthorStatus(WorksTheatreBridge._statusId, text);
419	  }
420	
421	  private async _exportSaveFile(): Promise<void> {
422	    const saveFile = sanitizeWorksSaveFile(
423	      TheatreStudioService.createContentOfSaveFile(WORKS_THEATRE_PROJECT_ID),
424	    );
425	    if (!saveFile) {
426	      this._renderStatus("EXPORT FAILED");
427	      return;
428	    }
429	    const raw = JSON.stringify(saveFile, null, 2);
430	    if (!TheatreStudioService.downloadFile(raw, { fileName: "works.json" })) {
431	      this._renderStatus("EXPORT BLOCKED");
432	      return;
433	    }
434	    this._renderStatus("STATE JSON DOWNLOADED");
435	  }
436	}
