59	function hasWorksTheatreSheetState(value: unknown): boolean {
60	  if (value == null || typeof value !== "object" || Array.isArray(value)) {
61	    return false;
62	  }
63	  const state = value as Record<string, unknown>;
64	  const sheetsById = state.sheetsById;
65	  if (sheetsById == null || typeof sheetsById !== "object" || Array.isArray(sheetsById)) {
66	    return false;
67	  }
68	  return Object.prototype.hasOwnProperty.call(sheetsById, "works");
69	}
