71	export function readWorksTheatreConfigSource(): WorksIntroTheatreConfig {
72	  const configState = worksIntroState as unknown as WorksIntroTheatreConfig;
73	  if (Array.isArray(configState.steps) && configState.steps.length > 0) {
74	    return {
75	      steps: configState.steps.map((step) => ({
76	        sheetId: "works",
77	        progressStart: step.progressStart,
78	        progressEnd: step.progressEnd,
79	        durationMs: Math.max(step.durationMs, WORKS_INTRO_DEFAULT_DURATION_MS),
80	      })),
81	    };
82	  }
83	  if (hasWorksTheatreSheetState(worksIntroState)) {
84	    return {
85	      steps: [
86	        {
87	          sheetId: "works",
88	          progressStart: 0,
89	          progressEnd: 1,
90	          durationMs: WORKS_INTRO_DEFAULT_DURATION_MS,
91	        },
92	      ],
